  const SCENES = Object.freeze([{"imageId": "cac_loai_chim_khu_vuon", "title": "Các loài chim trong vườn", "intro": "Khu vườn buổi sớm đang vang lên những tiếng lích chích rất vui. Trên cành cây, mỗi bạn chim có một chiếc mỏ, đôi chân và cách kiếm ăn khác nhau. Cô Thỏ Hồng sẽ đi thật chậm để bé kịp quan sát từng bạn.", "animals": ["chim_se", "bo_cau", "hoa_mi", "hut_mat", "go_kien"], "layout": "row5"}, {"imageId": "cac_loai_chim_nhiet_doi", "title": "Những sắc màu của chim nhiệt đới", "intro": "Bước vào khu rừng nhiệt đới, bé sẽ thấy màu sắc xuất hiện ở khắp nơi, từ chiếc mỏ của tu-can tới chiếc đuôi rực rỡ của chim công. Các bạn chim không chỉ đẹp mà còn có cách sống rất khác nhau.", "animals": ["vet", "hong_hac", "toucan", "boi_ca", "cong"], "layout": "poster5"}, {"imageId": "cac_loai_chim_san_moi", "title": "Những đôi mắt trên bầu trời", "intro": "Ở phòng này, Cô Thỏ mời bé ngước mắt lên cao. Có những loài chim dùng đôi mắt tinh, đôi cánh khỏe và chiếc mỏ đặc biệt để tìm thức ăn từ xa. Mỗi bạn lại có một cách bay rất riêng.", "animals": ["co", "dai_bang", "cu_meo", "dieu_hau", "chim_ung"], "layout": "poster5"}, {"imageId": "chim_nuoc_dam_lay", "title": "Bạn bè của vùng đầm nước", "intro": "Mặt hồ tưởng yên ắng nhưng thật ra rất đông vui. Có bạn bơi trên nước, có bạn đứng chân dài ở bờ, lại có bạn lao vun vút xuống bắt cá. Bé thử chạm từng bạn để nghe Cô Thỏ kể nhé.", "animals": ["thien_nga", "co_trang", "bo_nong", "boi_ca", "vit_troi"], "layout": "poster5"}, {"imageId": "con_trung_khu_vuon_1", "title": "Những vị khách tí hon trong vườn", "intro": "Giữa những bông hoa là cả một thế giới nhỏ xíu. Có bạn bay bằng đôi cánh mỏng, có bạn bò trên lá, có bạn cùng cả đàn làm việc. Càng nhìn gần, khu vườn càng có nhiều chuyện để kể.", "animals": ["buom", "ong_mat", "chuon_chuon", "bo_rua", "kien"], "layout": "poster5"}, {"imageId": "con_trung_khu_vuon_2", "title": "Dàn nhạc côn trùng", "intro": "Khi trời dịu nắng, khu vườn bắt đầu có những âm thanh và chuyển động rất thú vị. Dế cất tiếng, châu chấu bật nhảy, bọ ngựa đứng im như một chiếc lá. Cô Thỏ Hồng sẽ giới thiệu từng nghệ sĩ nhỏ cho bé.", "animals": ["chau_chau", "bo_ngua", "de_men", "dom_dom", "bo_canh_cung"], "layout": "poster5"}, {"imageId": "con_trung_sao_sang", "title": "Khu vườn khi trời tối", "intro": "Ban đêm không có nghĩa là khu vườn đi ngủ hết đâu. Nhiều sinh vật nhỏ bắt đầu bò, kêu hoặc phát sáng khi trời tối. Bé hãy tưởng tượng mình cầm một chiếc đèn pin nhỏ và khám phá thật nhẹ nhàng.", "animals": ["bo_rua", "sau_do", "thach_sung", "cuon_chieu", "ve_sau"], "layout": "poster5"}, {"imageId": "dai_duong_cuc_nam", "title": "Những người bạn vùng băng giá", "intro": "Gió lạnh thổi qua mặt biển và những tảng băng trắng. Ở nơi tưởng như quá lạnh để sống, vẫn có rất nhiều động vật khỏe mạnh và thông minh. Mỗi bạn có một chiếc áo hoặc một cách giữ ấm riêng.", "animals": ["chim_canh_cut", "ca_voi_sat_thu", "gau_trang", "hai_cau", "hai_ma"], "layout": "poster5"}, {"imageId": "dai_duong_day_bien", "title": "Chuyến lặn xuống đáy biển", "intro": "Cô Thỏ Hồng mời bé tưởng tượng mình đang ngồi trong một chiếc tàu ngầm tí hon. Càng lặn xuống, ánh sáng càng dịu và những sinh vật trước mắt càng lạ. Có bạn mềm như chiếc ô, có bạn mang cả ngôi nhà trên lưng.", "animals": ["ca_voi", "muc", "sua", "ca_ngua", "oc_bien"], "layout": "poster5"}, {"imageId": "dai_duong_san_ho_1", "title": "Rạn san hô rực rỡ - phòng 1", "intro": "Rạn san hô giống như một thành phố dưới biển với rất nhiều chỗ ẩn nấp và tìm thức ăn. Mỗi sinh vật trong tranh có một hình dáng khác nhau, nhưng tất cả đều phụ thuộc vào một môi trường biển khỏe mạnh.", "animals": ["ca_heo", "rua_bien", "ca_he", "sao_bien", "bach_tuoc"], "layout": "poster5"}, {"imageId": "dai_duong_san_ho_2", "title": "Rạn san hô rực rỡ - phòng 2", "intro": "Ở căn phòng tiếp theo, các bạn biển trông mạnh mẽ hơn một chút. Có bạn bơi rất nhanh, có bạn bò ngang dưới đáy và có bạn xòe thân như đang bay trong nước. Bé chạm thử từng bạn nhé.", "animals": ["ca_map", "ca_duoi", "cua_bien", "tom_hum", "ca_ngu"], "layout": "poster5"}, {"imageId": "dong_vat_rung_nhiet_doi", "title": "Bí mật rừng mưa nhiệt đới", "intro": "Rừng mưa xanh um là nơi mỗi tầng cây đều có cư dân riêng. Có bạn sống trên cành, có bạn ẩn dưới lá và có bạn bước thật êm trong bóng rừng. Cô Thỏ sẽ kể cho bé nghe vì sao mỗi bạn lại hợp với ngôi nhà này.", "animals": ["tac_ke", "toucan", "con_luoi", "ech", "bao_dom"], "layout": "poster5"}, {"imageId": "dong_vat_vung_cuc", "title": "Cuộc sống ở miền tuyết trắng", "intro": "Trên vùng đất phủ tuyết, thức ăn khó tìm và gió rất lạnh. Thế nhưng cáo, thỏ, cú, gấu và tuần lộc đều có những cách tuyệt vời để thích nghi. Bé thử tìm xem ai có bộ lông trắng nhất nhé.", "animals": ["cao_bac_cuc", "tho_trang", "cu_tuyet", "gau_trang", "tuan_loc"], "layout": "poster5"}, {"imageId": "gia_cam_nong_trai", "title": "Sân gia cầm buổi sáng", "intro": "Nông trại vừa sáng lên là sân gia cầm đã rộn ràng. Gà trống gáy, gà mẹ dẫn con, vịt và ngỗng đi tìm thức ăn, còn gà tây bước chậm rãi. Đây là một gia đình rất đông vui.", "animals": ["ga_trong", "ga_mai", "ga_con", "vit_xiem", "ngong", "ga_tay"], "layout": "poster6"}, {"imageId": "gia_suc_nong_trai_1", "title": "Những người bạn lớn ở nông trại", "intro": "Cánh đồng cỏ rộng là nơi nhiều vật nuôi lớn cùng sinh sống. Mỗi bạn có cách ăn cỏ, chạy, leo hoặc nghỉ ngơi khác nhau. Cô Thỏ Hồng sẽ dẫn bé đi chào từng bạn một.", "animals": ["bo", "trau", "lon", "cuu", "de", "ngua"], "layout": "poster6"}, {"imageId": "gia_suc_nong_trai_2", "title": "Những người bạn nhỏ ở nông trại", "intro": "Nông trại không chỉ có những bạn thật to. Ở góc sân này, lừa, thỏ, vịt, gà trống và ngỗng đang cùng xuất hiện. Bé hãy nhìn tai, chân, mỏ và bộ lông để phân biệt từng bạn.", "animals": ["lua", "tho", "vit", "ga_trong", "ngong"], "layout": "poster5"}, {"imageId": "hoang_da_dong_co_1", "title": "Những người khổng lồ của đồng cỏ", "intro": "Chào mừng bé đến với đồng cỏ châu Phi! Trước mắt là năm người bạn nổi tiếng: sư tử, hươu cao cổ, ngựa vằn, voi và tê giác. Mỗi bạn có một cách sinh tồn rất khác, nên bức tranh này giống như năm câu chuyện đặt cạnh nhau.", "animals": ["su_tu", "huou_cao_co", "ngua_van", "voi", "te_giac"], "layout": "savanna5"}, {"imageId": "hoang_da_dong_co_2", "title": "Quanh hồ nước đồng cỏ", "intro": "Một hồ nước nhỏ có thể trở thành điểm hẹn của rất nhiều động vật. Linh dương chạy nhanh, đà điểu cao lớn, hà mã thích nước và linh cẩu luôn quan sát xung quanh. Bé chạm vào từng bạn để xem ai có bí mật thú vị nhất nhé.", "animals": ["linh_duong", "da_dieu", "ha_ma", "linh_cau"], "layout": "savanna4"}, {"imageId": "hoang_da_rung_xanh_1", "title": "Những bước chân trong rừng xanh", "intro": "Rừng xanh có nhiều tầng bóng tối và ánh sáng. Hổ, khỉ, báo hoa mai, sóc và gấu mỗi bạn chọn một cách sống khác nhau: người leo cây, người đi dưới đất, người ẩn sau bụi rậm. Hãy cùng Cô Thỏ tìm dấu hiệu nhận ra từng bạn.", "animals": ["ho", "khi", "bao_hoa_mai", "soc", "gau"], "layout": "poster5"}, {"imageId": "hoang_da_rung_xanh_2", "title": "Những khuôn mặt đáng yêu của rừng", "intro": "Không phải bạn nào trong rừng cũng to lớn. Cáo đỏ, nai, gấu trúc, gấu mèo và nhím có những chiếc tai, cái đuôi và bộ lông rất khác nhau. Bé sẽ thấy mỗi bạn đáng nhớ theo một cách riêng.", "animals": ["cao_do", "nai", "gau_truc", "gau_meo", "nhim"], "layout": "poster5"}, {"imageId": "khu_vuon_con_trung", "title": "Một ngày bận rộn trong vườn", "intro": "Hoa nở làm khu vườn trở thành điểm hẹn của rất nhiều sinh vật nhỏ. Bướm và ong ghé hoa, bọ rùa bò trên lá, ốc sên đi chậm rãi, còn châu chấu bật nhảy. Mỗi bước chân nhỏ đều góp phần làm khu vườn sinh động.", "animals": ["buom", "ong_mat", "bo_rua", "oc_sen", "chau_chau"], "layout": "poster5"}, {"imageId": "khung_long_rung_xanh_1", "title": "Bảo tàng khủng long", "intro": "Cánh cửa thời gian mở ra và bé đang đứng giữa một khu rừng hàng triệu năm trước. Có loài săn mồi, có loài ăn cây, có bạn mang sừng, có bạn mặc áo giáp. Cô Thỏ sẽ kể rõ bạn nào thật sự là khủng long và bạn nào là bò sát bay sống cùng thời.", "animals": ["t_rex", "co_dai", "ba_sung", "khung_long_canh", "khung_long_giap"], "layout": "poster5"}, {"imageId": "khung_long_rung_xanh_2", "title": "Những người bạn tiền sử", "intro": "Ở phòng tiền sử này, bé sẽ gặp một khủng long có lưng như cánh buồm, một bạn có những tấm xương lớn trên lưng, một raptor nhỏ nhanh nhẹn và một em bé khủng long mới nở. Mỗi hóa thạch mới lại giúp chúng ta hiểu thêm về thế giới xưa.", "animals": ["spinosaurus", "stegosaurus", "raptor", "khung_long_con"], "layout": "poster4"}, {"imageId": "sinh_vat_ao_ho", "title": "Ao hồ ngay bên chúng ta", "intro": "Chỉ một ao nước nhỏ cũng có thể là ngôi nhà của rất nhiều sinh vật. Trên bờ có ếch và chuồn chuồn, dưới nước có nòng nọc, cá, cua và ốc. Bé hãy tưởng tượng mình đang ngồi thật yên bên bờ ao để quan sát.", "animals": ["ech", "nong_noc", "cua_dong", "oc_nhoi", "ca_ro", "chuon_chuon"], "layout": "poster6"}, {"imageId": "sinh_vat_bien_xinh_dep", "title": "Năm người bạn biển cả", "intro": "Biển có những sinh vật hình dáng lạ đến mức giống như nhân vật trong truyện. Có cá dẹt nhiều màu, cá phồng tròn, sò cứng, hải sâm mềm và cá bống nhỏ. Cô Thỏ sẽ kể vì sao mỗi hình dáng ấy đều có ích.", "animals": ["ca_than_tien", "ca_noc", "so_ngoc", "hai_sam", "ca_bong"], "layout": "poster5"}, {"imageId": "sinh_vat_tien_su", "title": "Kỷ băng hà và những loài đã biến mất", "intro": "Bé đang bước vào một căn phòng đặc biệt vì nhiều bạn trong tranh không còn sống trên Trái Đất ngày nay. Voi ma mút, hổ răng kiếm, dodo và thú giáp lớn giúp chúng ta tưởng tượng thế giới cổ xưa; tuần lộc là người bạn vẫn còn tồn tại tới hôm nay.", "animals": ["voi_ma_mut", "ho_rang_kiem", "dodo", "thu_giap_lon", "tuan_loc"], "layout": "poster5"}, {"imageId": "thu_cung_trong_nha_1", "title": "Những người bạn sống cùng gia đình - phòng 1", "intro": "Thú cưng mang niềm vui vào ngôi nhà nhưng mỗi loài cần một cách chăm sóc khác nhau. Chó cần vận động, mèo cần chỗ nghỉ, chim cần không gian, hamster cần nơi ẩn và rùa cần môi trường phù hợp. Yêu động vật bắt đầu từ việc hiểu chúng cần gì.", "animals": ["cho", "meo", "yen_phung", "hamster", "rua"], "layout": "poster5"}, {"imageId": "thu_cung_trong_nha_2", "title": "Những người bạn sống cùng gia đình - phòng 2", "intro": "Căn phòng này có năm gương mặt rất quen: mèo, chó, thỏ, cá và nhím. Không phải con vật dễ thương nào cũng cần cùng một loại thức ăn hay cùng một chỗ ở. Cô Thỏ sẽ giúp bé nhìn từng bạn bằng đôi mắt của một người chăm sóc có trách nhiệm.", "animals": ["meo", "cho", "tho", "ca_canh", "nhim"], "layout": "poster5"}, {"imageId": "dv_doi_tai_xau_xi", "title": "Ba người bạn trong vườn", "intro": "Giữa khu vườn có ba người bạn rất khác nhau: thỏ tai dài, nhím đầy gai và sóc có chiếc đuôi xù. Nếu chỉ nhìn vẻ ngoài, ai cũng thật khác; nhưng mỗi đặc điểm đều có lý do riêng. Cô Thỏ muốn bé khám phá điều đáng yêu ở từng bạn.", "animals": ["tho", "nhim", "soc"], "layout": "friends3"}, {"imageId": "dv_sinh_nhat_voi_con", "title": "Bữa tiệc sinh nhật của voi con", "intro": "Hôm nay căn phòng ấm áp hơn vì voi con đang có một bữa tiệc nhỏ. Sóc, thỏ và hươu mang quà tới chúc mừng. Trong lúc ngắm bánh và những chiếc hộp màu sắc, bé cũng có thể khám phá từng người bạn động vật trong bữa tiệc.", "animals": ["voi", "soc", "tho", "huou"], "layout": "party4"}, {"imageId": "khung_long_dam_lay", "title": "Bên hồ nước thời tiền sử", "intro": "Bé đang đứng bên một hồ nước rộng từ hàng triệu năm trước. Có bạn cổ dài đang gặm lá, có bạn mào ống đứng trên bờ, có bạn bay lượn trên trời và một bạn đang bơi dưới nước. Cô Thỏ sẽ kể xem bạn nào là khủng long thật, bạn nào chỉ sống cùng thời với khủng long.", "animals": ["thang_lan_co_ran", "co_dai", "khung_long_mo_vit", "khung_long_canh", "raptor"], "layout": "poster5", "id": 31}, {"imageId": "the_gioi_khung_long_con", "title": "Nhà trẻ khủng long", "intro": "Chào mừng bé đến nhà trẻ của các bạn khủng long nhỏ! Có bạn vừa chui ra khỏi vỏ trứng, có bạn đang chơi xếp khối, có bạn đang tập bay. Khi lớn lên, các bạn ấy sẽ trở nên rất to lớn. Bé chạm vào từng bạn để nghe Cô Thỏ kể nhé.", "animals": ["t_rex", "co_dai", "ba_sung", "stegosaurus", "khung_long_canh"], "layout": "poster5", "id": 32}, {"imageId": "kien_va_chim_bo_cau", "title": "Kiến và chim bồ câu", "intro": "Một chú kiến nhỏ không may bị rơi xuống hồ nước. Chim bồ câu trên cành thấy vậy liền thả một chiếc lá xuống để kiến bám vào và bơi vào bờ. Câu chuyện nhắc bé rằng giúp đỡ người khác, dù nhỏ bé, cũng là một việc làm thật đẹp.", "animals": ["kien", "bo_cau"], "layout": "friends3", "id": 33}, {"imageId": "dv_cuoc_thi_tai_nang_rung_xanh", "title": "Cuộc thi tài năng trong rừng", "intro": "Hôm nay khu rừng tổ chức một cuộc thi tài năng thật vui. Voi biểu diễn trên sân khấu, sóc leo cành thật nhanh, còn các bạn thỏ, cáo, cú mèo và lửng ngồi xem rồi vỗ tay cổ vũ. Bé tìm từng bạn trong tranh và nghe Cô Thỏ kể nhé.", "animals": ["voi", "soc", "tho", "cao_do", "cu_meo", "lung"], "layout": "party4", "id": 34}].map((scene, index) => Object.freeze({ ...scene, id: index + 1, animals: Object.freeze(scene.animals.slice()) })));

  const esc = (value) => String(value == null ? "" : value)
    .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;").replace(/'/g, "&#39;");

